/* ─── src/pages/Register.tsx ──────────────────────────────────────
   Registration form – mirrors UserRegister schema validation on
   the client before sending.                                       */

import React, { useState, useCallback } from "react";
import { useNavigate, Link } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import Toast from "../components/Toast";

export default function Register() {
  const { register } = useAuth();
  const navigate = useNavigate();

  const [fullName, setFullName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [toast, setToast] = useState<{ msg: string; type: "success" | "error" } | null>(null);

  // ── client validation ───────────────────────────
  const validate = (): string | null => {
    if (!fullName.trim()) return "Full name is required";
    if (fullName.trim().length < 2) return "Full name must be at least 2 characters";
    if (!/^[A-Za-z\s'\-]+$/.test(fullName.trim())) return "Full name contains invalid characters";
    if (!email.trim()) return "Email is required";
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())) return "Enter a valid email";
    if (!password) return "Password is required";
    if (password.length < 8) return "Password must be at least 8 characters";
    if (!/[A-Z]/.test(password)) return "Password needs an uppercase letter";
    if (!/[a-z]/.test(password)) return "Password needs a lowercase letter";
    if (!/[0-9]/.test(password)) return "Password needs a digit";
    if (password !== confirmPassword) return "Passwords do not match";
    return null;
  };

  const handleSubmit = useCallback(async (e: React.FormEvent) => {
    e.preventDefault();
    const err = validate();
    if (err) { setToast({ msg: err, type: "error" }); return; }

    setLoading(true);
    try {
      await register({ full_name: fullName.trim(), email: email.trim(), password });
      setToast({ msg: "Account created!", type: "success" });
      setTimeout(() => navigate("/dashboard"), 600);
    } catch (error: unknown) {
      setToast({ msg: (error as Error).message || "Registration failed", type: "error" });
    } finally {
      setLoading(false);
    }
  }, [fullName, email, password, confirmPassword, register, navigate]);

  const inputStyle: React.CSSProperties = {
    width: "100%",
    boxSizing: "border-box",
    padding: "12px 16px",
    borderRadius: 10,
    border: "1px solid #334155",
    background: "#1e293b",
    color: "#f1f5f9",
    fontSize: 14,
    fontFamily: "'Inter', sans-serif",
    outline: "none",
    transition: "border-color .2s",
  };

  const labelStyle: React.CSSProperties = {
    color: "#94a3b8",
    fontSize: 13,
    fontWeight: 500,
    display: "block",
    marginBottom: 6,
  };

  return (
    <div
      style={{
        minHeight: "100vh",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: "linear-gradient(135deg, #0f172a 0%, #1e1b4b 100%)",
        padding: 24,
      }}
    >
      <Toast message={toast?.msg ?? null} type={toast?.type ?? "error"} onClose={() => setToast(null)} />

      <div
        style={{
          width: "100%",
          maxWidth: 440,
          background: "#1e293b",
          borderRadius: 18,
          padding: "40px 36px",
          border: "1px solid #334155",
          boxShadow: "0 20px 60px rgba(0,0,0,.4)",
        }}
      >
        {/* header */}
        <div style={{ textAlign: "center", marginBottom: 32 }}>
          <div
            style={{
              width: 52,
              height: 52,
              borderRadius: 14,
              background: "linear-gradient(135deg,#6366f1,#8b5cf6)",
              margin: "0 auto 16px",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontSize: 24,
            }}
          >
            ✓
          </div>
          <h1 style={{ color: "#f1f5f9", margin: 0, fontSize: 24, fontFamily: "'Outfit', sans-serif" }}>
            Create Account
          </h1>
          <p style={{ color: "#64748b", margin: "6px 0 0", fontSize: 14 }}>
            Join TaskFlow and stay organised
          </p>
        </div>

        {/* form */}
        <form onSubmit={handleSubmit}>
          <label style={labelStyle}>Full Name</label>
          <input
            type="text"
            value={fullName}
            onChange={(e) => setFullName(e.target.value)}
            placeholder="Jane Doe"
            style={inputStyle}
            onFocus={(e) => (e.target.style.borderColor = "#6366f1")}
            onBlur={(e) => (e.target.style.borderColor = "#334155")}
          />

          <label style={{ ...labelStyle, marginTop: 20 }}>Email</label>
          <input
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            placeholder="you@example.com"
            style={inputStyle}
            onFocus={(e) => (e.target.style.borderColor = "#6366f1")}
            onBlur={(e) => (e.target.style.borderColor = "#334155")}
          />

          <label style={{ ...labelStyle, marginTop: 20 }}>Password</label>
          <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            placeholder="Min 8 chars, upper, lower, digit"
            style={inputStyle}
            onFocus={(e) => (e.target.style.borderColor = "#6366f1")}
            onBlur={(e) => (e.target.style.borderColor = "#334155")}
          />

          <label style={{ ...labelStyle, marginTop: 20 }}>Confirm Password</label>
          <input
            type="password"
            value={confirmPassword}
            onChange={(e) => setConfirmPassword(e.target.value)}
            placeholder="Re-enter password"
            style={inputStyle}
            onFocus={(e) => (e.target.style.borderColor = "#6366f1")}
            onBlur={(e) => (e.target.style.borderColor = "#334155")}
          />

          <button
            type="submit"
            disabled={loading}
            style={{
              width: "100%",
              marginTop: 28,
              padding: "13px 0",
              borderRadius: 10,
              border: "none",
              background: loading ? "#4338ca" : "linear-gradient(135deg,#6366f1,#8b5cf6)",
              color: "#fff",
              fontSize: 15,
              fontWeight: 600,
              cursor: loading ? "not-allowed" : "pointer",
              opacity: loading ? 0.7 : 1,
            }}
          >
            {loading ? "Creating…" : "Create Account"}
          </button>
        </form>

        <p style={{ textAlign: "center", marginTop: 24, color: "#64748b", fontSize: 13 }}>
          Already have an account?{" "}
          <Link to="/login" style={{ color: "#818cf8", textDecoration: "none", fontWeight: 600 }}>
            Sign In
          </Link>
        </p>
      </div>
    </div>
  );
}
